import { Controller } from '@nestjs/common';
import { MessagePattern, Payload } from '@nestjs/microservices';
import { KycService } from '../services/kyc.service';

interface KycFetchRequest {
  documentId: string;
  requestingUserId: string;
  officerRole?: string;
}

@Controller()
export class KycConsumerController {
  constructor(private readonly kycService: KycService) {}

  @MessagePattern({ cmd: 'fetch_kyc_document' })
  async handleKycFetch(@Payload() data: KycFetchRequest) {
    if (!data.requestingUserId) {
      return { error: 'Unauthenticated microservice request', status: 401 };
    }

    const record = await this.kycService.findDocumentById(data.documentId);
    if (!record) {
      return { error: 'KYC Document not found', status: 404 };
    }

    // Verify requesting user is the document owner or an authorized compliance officer
    const isOwner = record.userId === data.requestingUserId;
    const isComplianceOfficer = data.officerRole === 'COMPLIANCE_OFFICER';

    if (!isOwner && !isComplianceOfficer) {
      return { error: 'Unauthorized access to KYC record', status: 403 };
    }

    return {
      documentId: record.id,
      patientSsn: record.taxNumber,
      passportScanUrl: record.s3SignedUrl,
      status: record.verificationStatus
    };
  }
}
